GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _kvpr(mlist):
    """KVPR of a single GPU's model list (0 if empty or no free memory)."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU with the lowest current KVPR that fits."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_ratio = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] > 0:
                ratio = load[g] / free[g]
                if ratio < best_ratio:
                    best_ratio, best_idx = ratio, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _refine(p, gpu_num):
    """Hill-climb: repeatedly move or swap a model off the worst-KVPR GPU
    whenever it strictly lowers the max KVPR, until no improvement exists."""
    k = [_kvpr(p[g]) for g in range(gpu_num)]
    for _ in range(100):
        wg = max(range(gpu_num), key=lambda g: k[g])
        if k[wg] <= 0:
            break
        old_max, improved = max(k), False
        for m in list(p[wg]):
            # try moving m to another GPU
            for g in range(gpu_num):
                if g == wg or m.model_size > GPU_MEM_SIZE - sum(x.model_size for x in p[g]):
                    continue
                p[wg].remove(m); p[g].append(m)
                nk = [_kvpr(p[i]) for i in range(gpu_num)]
                if max(nk) < old_max:
                    k, improved = nk, True
                    break
                p[g].remove(m); p[wg].append(m)
            # try swapping m with a model on another GPU
            if not improved:
                for g in range(gpu_num):
                    if g == wg:
                        continue
                    for m2 in list(p[g]):
                        free_w = GPU_MEM_SIZE - sum(x.model_size for x in p[wg]) + m.model_size
                        free_g = GPU_MEM_SIZE - sum(x.model_size for x in p[g]) + m2.model_size
                        if m2.model_size > free_w or m.model_size > free_g:
                            continue
                        p[wg].remove(m); p[g].remove(m2)
                        p[wg].append(m2); p[g].append(m)
                        nk = [_kvpr(p[i]) for i in range(gpu_num)]
                        if max(nk) < old_max:
                            k, improved = nk, True
                            break
                        p[wg].remove(m2); p[g].remove(m)
                        p[wg].append(m); p[g].append(m2)
                    if improved:
                        break
            if improved:
                break
        if not improved:
            break
    return p


def compute_model_placement(gpu_num, models):
    """
    Best-of-4 greedy placement minimizing max KVPR: for each of several model
    orderings, greedily place every model on the GPU with the lowest current
    KVPR that fits in memory, refine each with a move/swap hill-climb, and
    return the placement with the lowest overall max KVPR.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) * m.model_size, reverse=True),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is None:
            continue
        p = _refine(p, gpu_num)
        mx = max(_kvpr(mlist) for mlist in p.values())
        if mx < best_max:
            best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return best

